             'env_names':[x.split('=',1)[0] for x in cfg.get('Env',[])], 'capabilities':hc.get('CapAdd'),
             'security_opt':hc.get('SecurityOpt'),'restart':hc.get('RestartPolicy'),'labels':sorted(labels),
